def find_words(board, words):
    root = {}
    WORD_KEY = '$'

    for word in words:
        node = root
        for ch in word:
            node = node.setdefault(ch, {})
        node[WORD_KEY] = word

    rows, cols = len(board), len(board[0])
    found = set()

    def dfs(r, c, parent):
        ch = board[r][c]
        node = parent.get(ch)
        if node is None:
            return

        word_match = node.get(WORD_KEY)
        if word_match is not None:
            found.add(word_match)
            node[WORD_KEY] = None

        board[r][c] = '#'
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] != '#':
                dfs(nr, nc, node)
        board[r][c] = ch

        if not node:
            parent.pop(ch, None)

    for r in range(rows):
        for c in range(cols):
            dfs(r, c, root)

    return sorted(found)

